#!/usr/bin/env python3
"""Independently rewrite English B-IV-8 guided-discussion questions."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "questions/english"
LESSON = "lesson-english-content-b-iv-8"
SOURCES = [
    ("https://www.yacjh.kh.edu.tw/upload/221/101_30637/114%E4%B8%8B%E5%AD%B8%E6%9C%9F%E7%AC%AC%E4%B8%80%E6%AC%A1%E6%AE%B5%E8%80%83%E4%B8%89%E5%B9%B4%E7%B4%9A%E8%8B%B1%E6%96%87.pdf", "高雄市立鹽埕國民中學公開英文段考", "對話、意見、理由與情境回應"),
    ("https://www.bhjh.ntpc.edu.tw/p/406-1000-10627%2Cr111.php?Lang=zh-tw", "新北市立北投國民中學公開定期評量試題頁", "短對話、功能語言與推論"),
    ("https://www.hcjh.ntpc.edu.tw/p/406-1000-7527%2Cr146.php", "新北市立新埔國民中學公開段考試題頁", "會話、資訊整合與情境應用"),
]

def refs():
    return [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "english", "locator": l, "observedPattern": "公立學校英語評量以討論中的表達意見、補充證據、釐清、附理由同意、建設性異議、分工、摘要、時間管理與整合結論判斷合宜回應；本題採全新討論情境。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u, t, l in SOURCES]

DATA = [
    ("opinion", "The class is discussing a school garden. Which sentence clearly gives a personal opinion about the plan?", ["I think a garden would make our courtyard more welcoming.", "The courtyard opinion is a purple Tuesday.", "I am an idea at four o'clock.", "No one is allowed to discuss gardens."], "A", "I think introduces a personal opinion and the rest states a view about the garden plan.", "先找表示意見的語塊，再檢查後半句是否真的回應討論主題。", ["Identify the discussion topic school garden.", "Look for a phrase that marks personal belief.", "Confirm that the rest comments on the plan.", "Choose I think a garden would help.", "Reject grammatical nonsense and conversation-closing lines."]),
    ("evidence", "A classmate says, 'The new water station is useful.' Which reply supports that claim with observable evidence?", ["Students refilled their bottles there thirty times today.", "Useful is a yellow cloud.", "I agree because I feel sleepy.", "The station should sing to the class."], "A", "Thirty refills are an observable fact that supports the claim that the water station is useful.", "證據題要找可觀察、可計數或可核對的事實，而非再次表態或離題。", ["Identify the claim about usefulness.", "Ask which option could be checked in the real world.", "Match thirty refills to use of the station.", "Choose the measurable classroom fact.", "Reject feelings, personification, and unrelated descriptions."]),
    ("clarification", "A partner says, 'We need to improve the school entrance.' Which question asks the partner to explain the plan more precisely?", ["Which part should we change first?", "Why is the entrance a sandwich?", "I improved the entrance last yesterday.", "Do not tell me what you mean."], "A", "Which part should we change first narrows the broad proposal into a specific action to discuss.", "釐清題要把寬泛主張轉成可回答的範圍、對象或優先順序。", ["Notice that improve the entrance is broad.", "Find a question asking for a concrete part or first step.", "Check that which part keeps the same topic.", "Choose the clarification question.", "Reject nonsense and statements that block explanation."]),
    ("reasoned agreement", "Someone proposes a quiet study table in the library. Which reply agrees and gives a relevant reason?", ["I agree because some readers need a place without noise.", "I agree because the table ate breakfast.", "Nobody can explain an agreement.", "Quiet tables are next year."], "A", "I agree states support, and because introduces a reason connected to readers' needs.", "同意加理由要同時看到支持語與能解釋支持原因的 because 子句。", ["Identify the proposed quiet table.", "Find a phrase that accepts the idea.", "Read the reason after because.", "Check that noise relates to studying.", "Choose the complete agreement with a relevant reason."]),
    ("constructive disagreement", "A group wants to hold a cleanup on Sunday, but you are unavailable. Which response disagrees constructively?", ["I understand the plan, but could we choose Saturday instead?", "Your plan is stupid; end the meeting.", "Sunday is a window and Saturday is rain.", "I disagree and have no alternative."], "A", "The response acknowledges the plan, states a different preference, and offers a usable alternative without insulting anyone.", "建設性異議要保留尊重、說明差異並提出可行替代方案。", ["Identify the proposed day Sunday.", "Notice that the speaker cannot attend.", "Find an alternative day.", "Check that the opening acknowledges the group.", "Choose the respectful Saturday proposal."]),
    ("fair division", "Four students are preparing a display, but nobody knows who will do each part. Which suggestion organizes the work fairly?", ["Let's list the tasks and let everyone choose one.", "One student should do every task silently.", "The display will finish without any work.", "I will hide the materials from the group."], "A", "Listing tasks and allowing each person to choose makes the responsibilities visible and supports fair participation.", "分工題要找讓任務透明、讓成員參與且能實際執行的方案。", ["Identify the problem: unclear responsibilities.", "Look for a way to make tasks visible.", "Check whether all four students can participate.", "Choose the list-and-choose proposal.", "Reject overloading one person, magical completion, and sabotage."]),
    ("summary", "The group agrees to borrow tools, work in pairs, and return everything on Friday. Which sentence summarizes the decision?", ["So we will borrow the tools, work in pairs, and return them on Friday.", "The group chose a purple bicycle instead.", "Nobody made a decision.", "The tools will return the students."], "A", "So introduces a summary and the sentence preserves all three agreed actions and the deadline.", "摘要題逐項比對原討論的行動、合作方式與時間，不加入新資訊。", ["List the three agreed actions.", "Find a sentence beginning with a summary marker.", "Check tools, pairs, and Friday one by one.", "Choose the sentence containing all details.", "Reject options that deny the decision or change participants and objects."]),
    ("time management", "The discussion has one minute left and the group still needs a choice. What should the chairperson say?", ["We have one minute; let's hear one last idea and then vote.", "There is unlimited time, so we can ignore the clock.", "The clock will choose our project by itself.", "Everyone must leave without deciding."], "A", "The chair sets the limit, permits one final contribution, and names a fair way to decide.", "時間管理回應要承認限制、安排最後發言並提供決策程序。", ["Identify the one-minute limit.", "Find a sentence that uses the remaining time purposefully.", "Check for a final chance to contribute.", "Confirm that voting creates a decision.", "Choose the chairperson's organized proposal."]),
    ("inclusive invitation", "One member has been quiet during the meeting. Which invitation respects that person's choice while opening the discussion?", ["Would you like to share an idea, or would you rather pass?", "You must speak now or lose your turn forever.", "Only the loudest member matters.", "I will speak for you without asking."], "A", "The invitation encourages participation but also gives the quiet member the option to pass.", "包容性回應要邀請發言，同時保留對方拒絕或暫不發言的自主權。", ["Notice that the member has not spoken.", "Look for an invitation rather than a command.", "Check whether the person may pass.", "Choose the respectful either-or question.", "Reject threats, exclusion, and speaking on someone's behalf."]),
    ("integrated conclusion", "The team wants safer crossings. A map shows a busy corner, a survey reports near misses, and the group can meet the principal. Which conclusion uses the information well?", ["The map and survey identify a risk, so we will show both to the principal and request a safer crossing.", "The map and survey are useless, so we will forget the problem.", "The principal is a map and the crossing can fix itself.", "We collected evidence but will not use it."], "A", "The conclusion connects two information sources to a specific next action while keeping the safety goal clear.", "整合結論要把證據、問題與下一步完整串起來，不能只重述或放棄行動。", ["Identify the goal safer crossings.", "Combine the map and survey as supporting evidence.", "Name the appropriate decision-maker principal.", "Choose the request for a safer crossing.", "Reject conclusions that discard evidence or assign actions to objects."]),
]

assert len(DATA) == 10
TARGETS = ["A", "B", "C", "D", "B", "C", "D", "A", "B", "C"]
for i, (tag, prompt, options, answer, explanation, strategy, steps) in enumerate(DATA, 1):
    target = TARGETS[i - 1]
    if target != answer:
        oi, ti = ord(answer) - 65, ord(target) - 65
        correct = options[oi]
        rest = [v for j, v in enumerate(options) if j != oi]
        options = rest[:ti] + [correct] + rest[ti:]
        answer = target
    item = {"id": f"question-english-content-b-iv-8-{i}", "subject": "english", "type": "single-choice", "prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(options)], "knowledgeIds": ["kg-english-content-b-iv-8"], "difficulty": "medium", "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "公立學校國中英語段考；只研究引導式討論、意見、證據、釐清、協商、摘要、時間管理與整合結論題型。", "authoringNote": "依官方英語文領域課綱、單元 KG 與三個公立學校公開來源，獨立改寫引導式討論題；未複製原文、選項、篇章、圖片或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-13", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}
    (OUT / f"question-english-content-b-iv-8-{i}.json").write_text(json.dumps(item, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(DATA)} independent questions for {LESSON}")
